func TestRPCLegacy(t *testing.T) {
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	s := grpc.NewServer()
	pbv3.RegisterSearchServiceV3Server(s, srv{})
	go s.Serve(lis)
	defer s.Stop()
	cc, err := grpc.Dial(lis.Addr().String(), grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Close()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	resp, err := pbv3.NewSearchServiceV3Client(cc).Search(ctx, &pbv3.SearchRequestV3{Query: "hello"})
	t.Logf("Search: %v, %v", resp, err)
	if err != nil {
		t.Errorf("RPC failed: %v", err)
	}
}

func TestStatusDetailsLegacy(t *testing.T) {
	st, err := status.New(codes.Internal, "x").WithDetails(&pbv3.SearchRequestV3{Query: "q"})
	if err != nil {
		t.Fatal(err)
	}
	d := st.Details()
	t.Logf("Details()[0] type = %T value=%v", d[0], d[0])
	if _, ok := d[0].(*pbv3.SearchRequestV3); !ok {
		t.Errorf("Details()[0] is %T, want *pbv3.SearchRequestV3", d[0])
	}
}

func TestBinlogLegacy(t *testing.T) {
	ml := binarylog.NewTruncatingMethodLogger(1<<20, 1<<20)
	e := ml.Build(&binarylog.ServerMessage{Message: &pbv3.SearchRequestV3{Query: "q"}})
	t.Logf("server message: len=%d data=%v", e.GetMessage().GetLength(), e.GetMessage().GetData())
	if e.GetMessage().GetLength() == 0 {
		t.Errorf("legacy message logged with empty payload")
	}
	e = ml.Build(&binarylog.ClientMessage{Message: &pbv3.SearchRequestV3{Query: "q"}})
	if e.GetMessage().GetLength() == 0 {
		t.Errorf("legacy client message logged with empty payload")
	}
}
